import crypto from 'node:crypto';
const jwt = require('jsonwebtoken');

export class RateLimiter {
  constructor(options = {}) {
    this.limit = options.limit || 5;
    this.windowMs = options.windowMs || 60000;
    this.attempts = new Map();
  }

  async isBlocked(key) {
    const entry = this.attempts.get(key) || { count: 0, resetAt: Date.now() + this.windowMs };
    if (Date.now() > entry.resetAt) {
      this.attempts.delete(key);
      return false;
    }
    return entry.count >= this.limit;
  }

  async recordFailure(key) {
    const now = Date.now();
    const entry = this.attempts.get(key) || { count: 0, resetAt: now + this.windowMs };
    entry.count += 1;
    this.attempts.set(key, entry);
  }

  async consume(key) {
    if (await this.isBlocked(key)) {
      return { allowed: false, remaining: 0 };
    }
    await this.recordFailure(key);
    const entry = this.attempts.get(key);
    return { allowed: true, remaining: Math.max(0, this.limit - entry.count) };
  }
}

export function validateInput(data) {
  if (!data || typeof data !== 'object') return { ok: false, error: 'Invalid payload' };
  if (!data.email || typeof data.email !== 'string' || !/^[\w.-]+@[\w.-]+\.\w+$/.test(data.email)) {
    return { ok: false, error: 'Invalid email' };
  }
  if (!data.password || typeof data.password !== 'string' || data.password.length < 8) {
    return { ok: false, error: 'Password must be at least 8 characters' };
  }
  return { ok: true };
}

export async function hashPassword(password) {
  const salt = crypto.randomBytes(16).toString('hex');
  const hash = crypto.scryptSync(password, salt, 64).toString('hex');
  return `${salt}:${hash}`;
}

export async function verifyPassword(password, storedHash) {
  if (!storedHash || !storedHash.includes(':')) return false;
  const [salt, key] = storedHash.split(':');
  const keyBuffer = Buffer.from(key, 'hex');
  const derivedKey = crypto.scryptSync(password, salt, 64);
  if (keyBuffer.length !== derivedKey.length) return false;
  return crypto.timingSafeEqual(keyBuffer, derivedKey);
}

export async function generateToken(payload, secret) {
  return jwt.sign(payload, secret, { expiresIn: '15m', issuer: 'contextos-auth', audience: 'contextos-api' });
}

export class AuthService {
  constructor(rateLimiter = new RateLimiter()) {
    this.rateLimiter = rateLimiter;
  }

  async hashPassword(pwd) { return hashPassword(pwd); }
  async verifyPassword(pwd, hash) { return verifyPassword(pwd, hash); }
  async generateToken(payload, secret) { return generateToken(payload, secret); }

  async handleLogin(request) {
    const clientIp = request.ip || 'unknown';
    if (await this.rateLimiter.isBlocked(clientIp)) {
      return { status: 429, body: { error: 'Too Many Requests' } };
    }

    const val = validateInput(request);
    if (!val.ok) {
      await this.rateLimiter.recordFailure(clientIp);
      return { status: 400, body: { error: val.error } };
    }

    return { status: 200, body: { success: true } };
  }
}

export function errorHandler(err, req, res) {
  res.status(500).json({ error: 'Internal Server Error' });
}

