export type OrderStatus = 'PENDING' | 'PAID' | 'SHIPPED' | 'CANCELLED';

export class Money {
  public readonly amount: number;
  public readonly currency: string;

  constructor(amount: number, currency: string = 'USD') {
    if (amount < 0) {
      throw new Error('Money amount cannot be negative');
    }
    this.amount = amount;
    this.currency = currency;
    Object.freeze(this);
  }

  static of(amount: number, currency: string = 'USD'): Money {
    return new Money(amount, currency);
  }

  add(other: Money): Money {
    if (this.currency !== other.currency) {
      throw new Error(`Currency mismatch: ${this.currency} vs ${other.currency}`);
    }
    return new Money(this.amount + other.amount, this.currency);
  }

  equals(other: Money): boolean {
    return this.amount === other.amount && this.currency === other.currency;
  }
}

export interface OrderItem {
  id: string;
  quantity: number;
  price: Money;
}

export class Order {
  public readonly id: string;
  public readonly customerId: string;
  public status: OrderStatus = 'PENDING';
  public items: OrderItem[] = [];
  private events: any[] = [];

  constructor(id: string, customerId: string) {
    this.id = id;
    this.customerId = customerId;
    this.events.push({ type: 'OrderCreated', orderId: id, customerId, timestamp: Date.now() });
  }

  addItem(productId: string, quantity: number, price: Money): void {
    if (quantity <= 0) {
      throw new Error('Quantity must be strictly positive');
    }
    if (this.status !== 'PENDING') {
      throw new Error(`Cannot add item to order in status ${this.status}`);
    }
    this.items.push({ id: productId, quantity, price });
  }

  pay(): void {
    if (this.status !== 'PENDING') {
      throw new Error('Can only pay for pending orders');
    }
    if (this.items.length === 0) {
      throw new Error('Cannot pay for empty order');
    }
    this.status = 'PAID';
    this.events.push({ type: 'OrderPaid', orderId: this.id, timestamp: Date.now() });
  }

  ship(): void {
    if (this.status !== 'PAID') {
      throw new Error('Order must be paid before shipping');
    }
    this.status = 'SHIPPED';
    this.events.push({ type: 'OrderShipped', orderId: this.id, timestamp: Date.now() });
  }

  cancel(): void {
    if (this.status === 'SHIPPED') {
      throw new Error('Cannot cancel an order that has already shipped');
    }
    this.status = 'CANCELLED';
    this.events.push({ type: 'OrderCancelled', orderId: this.id, timestamp: Date.now() });
  }

  getTotal(): Money {
    return this.items.reduce(
      (acc, item) => acc.add(new Money(item.price.amount * item.quantity, item.price.currency)),
      new Money(0, 'USD')
    );
  }

  getDomainEvents(): any[] {
    return [...this.events];
  }
}

export interface IOrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}

