export type CircuitState = 'CLOSED' | 'OPEN' | 'HALF_OPEN';

export interface CircuitBreakerOptions {
  failureThreshold?: number;
  resetTimeoutMs?: number;
}

export class ApiError extends Error {
  public readonly statusCode: number;
  constructor(message: string, statusCode: number = 500) {
    super(message);
    this.name = 'ApiError';
    this.statusCode = statusCode;
  }
}

export class CircuitBreaker {
  state: CircuitState = 'CLOSED';
  failureCount: number = 0;
  failureThreshold: number = 3;
  resetTimeoutMs: number = 1000;
  lastFailureTime: number = 0;

  constructor(options: CircuitBreakerOptions = {}) {
    if (options.failureThreshold) this.failureThreshold = options.failureThreshold;
    if (options.resetTimeoutMs) this.resetTimeoutMs = options.resetTimeoutMs;
  }

  getState(): CircuitState {
    if (this.state === 'OPEN' && Date.now() - this.lastFailureTime > this.resetTimeoutMs) {
      this.state = 'HALF_OPEN';
    }
    return this.state;
  }

  recordSuccess(): void {
    this.failureCount = 0;
    this.state = 'CLOSED';
  }

  recordFailure(): void {
    this.failureCount += 1;
    this.lastFailureTime = Date.now();
    if (this.failureCount >= this.failureThreshold) {
      this.state = 'OPEN';
    }
  }

  async execute<T>(action: () => Promise<T>): Promise<T> {
    if (this.getState() === 'OPEN') {
      throw new ApiError('Circuit breaker is OPEN', 503);
    }
    try {
      const result = await action();
      this.recordSuccess();
      return result;
    } catch (err) {
      this.recordFailure();
      throw err;
    }
  }
}

export interface RequestOptions {
  timeoutMs?: number;
  headers?: Record<string, string>;
}

export class ResilientHttpClient {
  circuitBreaker: any;
  constructor(circuitBreaker?: any) {
    this.circuitBreaker = circuitBreaker || new CircuitBreaker();
  }

  async get<T>(url: string, options: RequestOptions = {}): Promise<T> {
    const timeoutMs = options.timeoutMs || 5000;
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), timeoutMs);

    return this.circuitBreaker.execute(async () => {
      try {
        const res = await fetch(url, { signal: controller.signal, headers: options.headers });
        if (!res.ok) throw new ApiError(`HTTP ${res.status}`, res.status);
        return (await res.json()) as T;
      } finally {
        clearTimeout(timeout);
      }
    });
  }
}
